<?php
if($path==='/health'&&$method==='GET'){role('ADMIN');query('SELECT 1');send(['success'=>true,'database'=>'connected','backend'=>'PHP + MySQL']);}
if($path==='/departments'&&$method==='GET')send(['departments'=>visibleDepartments()]);
if($path==='/departments/divisions'&&$method==='GET'){$sql="SELECT cd.*,d.name department_name,d.code department_code,(SELECT COUNT(*) FROM students s WHERE s.division_id=cd.id AND s.is_active=1) student_count,(SELECT COUNT(*) FROM subjects sub WHERE sub.division_id=cd.id) subject_count FROM class_divisions cd JOIN departments d ON d.id=cd.department_id WHERE 1=1";$p=[];scopeSql($sql,$p,'cd.department_id');if(auth()['role']==='STUDENT'){$sql.=' AND cd.id=(SELECT division_id FROM students WHERE id=?)';$p[]=auth()['student_id'];}send(['divisions'=>rows($sql.' ORDER BY cd.year_level DESC,cd.division',$p)]);}
if($path==='/departments/divisions'&&$method==='POST'){role('ADMIN');need($body,['department_id','academic_year','year_level','division','semester']);$id=uid('div-');$data=array_intersect_key($body,array_flip(['department_id','academic_year','year_level','division','semester']));$data['year_level']=strtoupper($data['year_level']);$data['division']=strtoupper($data['division']);if(!in_array($data['year_level'],['FY','SY','TY']))fail('Year must be FY, SY or TY.');insertRow('class_divisions',['id'=>$id,...$data]);send(['message'=>'Division created successfully','id'=>$id],201);}
if($path==='/departments/subjects'&&$method==='GET'){$sql="SELECT sub.*,CONCAT(cd.year_level,' ',cd.division) division_name,(SELECT GROUP_CONCAT(u.full_name SEPARATOR ', ') FROM subject_faculty sf JOIN users u ON u.id=sf.faculty_user_id WHERE sf.subject_id=sub.id) faculty_names,(SELECT sf.faculty_user_id FROM subject_faculty sf WHERE sf.subject_id=sub.id LIMIT 1) primary_faculty_id FROM subjects sub JOIN class_divisions cd ON cd.id=sub.division_id WHERE 1=1";$p=[];scopeSql($sql,$p,'cd.department_id');if(auth()['role']==='STUDENT'){$sql.=' AND sub.division_id=(SELECT division_id FROM students WHERE id=?)';$p[]=auth()['student_id'];}filterSql($sql,$p,['division_id'=>'sub.division_id'],$q);send(['subjects'=>rows($sql.' ORDER BY sub.name',$p)]);}
if($path==='/departments/subjects'&&$method==='POST'){role('ADMIN');need($body,['division_id','code','name']);$id=uid('sub-');transaction(function()use($body,$id){insertRow('subjects',['id'=>$id,'division_id'=>$body['division_id'],'code'=>$body['code'],'name'=>$body['name'],'credits'=>$body['credits']??3]);if(!empty($body['faculty_user_id'])){if(!one("SELECT id FROM users WHERE id=? AND role IN ('ADMIN','FACULTY','HOD')",[$body['faculty_user_id']]))fail('Choose a Faculty or Admin account.');insertRow('subject_faculty',['id'=>uid(),'subject_id'=>$id,'faculty_user_id'=>$body['faculty_user_id']]);}});send(['message'=>'Subject created successfully','id'=>$id],201);}
if($path==='/departments/faculty-list'&&$method==='GET'){role();$sql="SELECT id,employee_id,full_name,email,department_id FROM users WHERE role IN ('FACULTY','HOD','ADMIN')";$p=[];scopeSql($sql,$p,'department_id');send(['faculty'=>rows($sql.' ORDER BY full_name',$p)]);}
if(in_array($path,['/settings','/face/settings'])){
 if($method==='GET'){if($path==='/face/settings')role('ADMIN');send(['settings'=>settings()]);}
 if($method==='PUT'){role('ADMIN');$allowed=$path==='/settings'?['critical_threshold','warning_threshold','edit_window_hours','allow_faculty_late_marking','college_name','department_name','board_name']:['face_match_threshold','min_face_quality','max_image_size_mb','duplicate_protection','require_confirmation'];$data=array_intersect_key($body,array_flip($allowed));$s=settings();$merged=[...$s,...$data];if($merged['critical_threshold']<0||$merged['warning_threshold']>100||$merged['critical_threshold']>=$merged['warning_threshold'])fail('Thresholds must satisfy 0 <= critical < warning <= 100.');if($merged['edit_window_hours']<0||$merged['edit_window_hours']>8760)fail('Invalid edit window.');foreach(['face_match_threshold','min_face_quality'] as $k)if($merged[$k]<0||$merged[$k]>1)fail($k.' must be between 0 and 1.');if($merged['max_image_size_mb']<1||$merged['max_image_size_mb']>10)fail('Image size limit must be 1–10 MB.');transaction(function()use($path,$data,$s){updateRow('system_settings',$s['id'],$data);if($path==='/face/settings')logBio('SETTINGS_UPDATE',null,'Face settings updated: '.json_encode($data));});send(['success'=>true,'message'=>'Settings updated successfully.','settings'=>settings()]);}
}
if($path==='/calendar'&&$method==='GET'){$sql='SELECT * FROM holiday_calendar WHERE 1=1';$p=[];if(!empty($q['year'])){$sql.=' AND event_date LIKE ?';$p[]=$q['year'].'-'.(!empty($q['month'])?str_pad($q['month'],2,'0',STR_PAD_LEFT):'').'%';}filterSql($sql,$p,['type'=>'type'],$q);send(['events'=>rows($sql.' ORDER BY event_date',$p)]);}
if($path==='/calendar'&&$method==='POST'){role('ADMIN');need($body,['event_date','title','type']);validateDate($body['event_date']);if(!in_array($body['type'],['NATIONAL','REGIONAL_MAHARASHTRA','COLLEGE_EVENT']))fail('Invalid calendar type.');$old=one('SELECT id FROM holiday_calendar WHERE event_date=?',[$body['event_date']]);$id=$old['id']??uid('cal-');$d=['event_date'=>$body['event_date'],'title'=>$body['title'],'type'=>$body['type'],'is_instructional_day'=>!empty($body['is_instructional_day'])?1:0,'description'=>$body['description']??null];if($old)updateRow('holiday_calendar',$id,$d);else insertRow('holiday_calendar',['id'=>$id,...$d]);send(['message'=>'Calendar event added/updated successfully','id'=>$id],201);}
if(preg_match('#^/calendar/([^/]+)$#',$path,$m)&&$method==='DELETE'){role('ADMIN');query('DELETE FROM holiday_calendar WHERE id=?',[$m[1]]);send(['message'=>'Calendar event deleted successfully']);}
if($path==='/defaulters'&&$method==='GET'){role();$sessions=validSessions($q);$list=[];foreach(studentRows($q) as $st){$stats=statsFor($st,$sessions);$list[]=[...$st,'student_id'=>$st['id'],...$stats];}usort($list,fn($a,$b)=>$a['attendance_percentage']<=>$b['attendance_percentage']);$cats=array_count_values(array_column($list,'status_category'));send(['summary'=>['totalStudents'=>count($list),'totalConducted'=>count($sessions),'criticalCount'=>$cats['CRITICAL']??0,'warningCount'=>$cats['WARNING']??0,'safeCount'=>$cats['SAFE']??0,'averageAttendance'=>count($list)?round(array_sum(array_column($list,'attendance_percentage'))/count($list),2):100,'thresholds'=>thresholds(),'excludedHolidaysCount'=>(int)one('SELECT COUNT(*) n FROM holiday_calendar WHERE is_instructional_day=0')['n']],'defaulters'=>$list]);}
if($path==='/defaulters/my-status'&&$method==='GET'){$u=auth();if(!$u['student_id'])fail('No student record linked to your account.',404);$st=student($u['student_id']);ownStudent($st);send(['student'=>[...$st,'student_id'=>$st['id'],...statsFor($st,validSessions(['division_id'=>$st['division_id']]))],'thresholds'=>thresholds()]);}
// Account administration (extra API, useful for setting up real Faculty/Student logins).
if($path==='/users'&&$method==='GET'){role('ADMIN');send(['users'=>rows('SELECT id,email,employee_id,full_name,role,department_id FROM users ORDER BY role,full_name')]);}
if($path==='/users'&&$method==='POST'){role('ADMIN');need($body,['email','password','full_name','role']);collegeEmail($body['email']);if(!filter_var($body['email'],FILTER_VALIDATE_EMAIL)||strlen($body['password'])<12)fail('Use a valid email and a password of at least 12 characters.');if(!in_array($body['role'],['ADMIN','FACULTY','HOD','STUDENT']))fail('Invalid account role.');if($body['role']==='STUDENT'&&!one('SELECT id FROM students WHERE is_active=1 AND (roll_no=? OR email=?)',[$body['employee_id']??'',strtolower($body['email'])]))fail('Create the student first and match their roll number or email.');$dept=$body['department_id']??null;if($body['role']!=='ADMIN'&&!one('SELECT id FROM departments WHERE id=?',[$dept]))fail('Select a valid department.');if($body['role']==='STUDENT'){$st=one('SELECT s.id FROM students s JOIN class_divisions cd ON cd.id=s.division_id WHERE s.is_active=1 AND cd.department_id=? AND s.email=?',[$dept,strtolower(trim($body['email']))]);if(!$st)fail('Student email must match an active student in this department.');}$id=uid('user-');insertRow('users',['id'=>$id,'email'=>strtolower(trim($body['email'])),'password_hash'=>password_hash($body['password'],PASSWORD_BCRYPT),'full_name'=>$body['full_name'],'role'=>$body['role'],'employee_id'=>($body['employee_id']??'')?:null,'department_id'=>$body['department_id']??null]);send(['success'=>true,'id'=>$id],201);}

if(preg_match('#^/users/([^/]+)/password$#',$path,$m)&&$method==='PUT'){role('ADMIN');need($body,['password']);if(strlen($body['password'])<12)fail('Use a password of at least 12 characters.');if(!one('SELECT id FROM users WHERE id=?',[$m[1]]))fail('Account not found.',404);updateRow('users',$m[1],['password_hash'=>password_hash($body['password'],PASSWORD_BCRYPT)]);send(['success'=>true,'message'=>'Password updated.']);}

function visibleDepartments(){$u=auth();if($u['role']==='ADMIN')return rows('SELECT * FROM departments ORDER BY code');if($u['role']==='STUDENT')return rows('SELECT d.* FROM departments d JOIN class_divisions cd ON cd.department_id=d.id JOIN students s ON s.division_id=cd.id WHERE s.id=?',[$u['student_id']]);return rows('SELECT * FROM departments WHERE id=?',[$u['department_id']]);}
if(preg_match('#^/users/([^/]+)/access$#',$path,$m)&&$method==='PUT'){role('ADMIN');need($body,['role']);if(!in_array($body['role'],['ADMIN','FACULTY','HOD','STUDENT']))fail('Invalid role.');$target=one('SELECT * FROM users WHERE id=?',[$m[1]])??fail('Account not found.',404);if($target['id']===auth()['id'])fail('Use another Admin account to change your own role.');$dept=$body['department_id']??null;if($body['role']!=='ADMIN'&&!one('SELECT id FROM departments WHERE id=?',[$dept]))fail('Select a department.');if($body['role']==='STUDENT'&&!one('SELECT s.id FROM students s JOIN class_divisions cd ON cd.id=s.division_id WHERE s.email=? AND s.is_active=1 AND cd.department_id=?',[$target['email'],$dept]))fail('Student email must match an active student in this department.');transaction(function()use($target,$body,$dept){$admins=rows("SELECT id FROM users WHERE role='ADMIN' FOR UPDATE");if($target['role']==='ADMIN'&&$body['role']!=='ADMIN'&&count($admins)<2)fail('Keep at least one Admin.');updateRow('users',$target['id'],['role'=>$body['role'],'department_id'=>$dept]);});send(['success'=>true]);}
